@startuml

class City {
  + name : string
  + inhabitants : int
}

class Attraction {
  + name : string
  + address : string
}

class GuidedTour {
  + duration : int
  + number : int
}

class Person {
  + name : string
}

class Visitor extends Person {}

class Guide extends Person {}

class Discount {
  + amount : float
}

City "1" *-- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "1" -- "1" Guide : requires
GuidedTour "1" -- "1..20" Visitor : takes part in
Visitor "0..*" -- "0..*" GuidedTour : receives
Discount "0..*" -- "1" Visitor : granted to
Discount "0..*" -- "1" GuidedTour : for

@enduml

